#!/usr/bin/env python3 -I
"""Read-only: counts the `resource` stored on every OAuth grant in the yukitools
OAUTH_KV namespace via the Cloudflare KV REST API. Prints counts only — no
grant ids, user ids or tokens. Needs CLOUDFLARE_API_TOKEN (Workers KV read)."""
import json, os, sys, urllib.request, collections

ACCT = "a94cb5880b72350ddbc9b930b374e83c"
NS = "d2546941d289468ebd7fe16dcff3c128"
BASE = f"https://api.cloudflare.com/client/v4/accounts/{ACCT}/storage/kv/namespaces/{NS}"
TOKEN = os.environ.get("CLOUDFLARE_API_TOKEN")
if not TOKEN:
    sys.exit("CLOUDFLARE_API_TOKEN not set")
HDR = {"Authorization": f"Bearer {TOKEN}", "content-type": "application/json"}
out = open(sys.argv[1], "w") if len(sys.argv) > 1 else sys.stdout


def call(method, url, body=None):
    req = urllib.request.Request(url, method=method, headers=HDR,
                                 data=json.dumps(body).encode() if body is not None else None)
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return json.load(r)
    except urllib.error.HTTPError as e:
        sys.exit(f"HTTP {e.code} on {method} {url.split('/namespaces/')[1][:40]}…: {e.read()[:300]!r}")


keys, cursor = [], ""
while True:
    page = call("GET", f"{BASE}/keys?prefix=grant:&limit=1000" + (f"&cursor={cursor}" if cursor else ""))
    keys += [k["name"] for k in page["result"]]
    cursor = (page.get("result_info") or {}).get("cursor") or ""
    if not cursor:
        break
print(f"grants: {len(keys)}", file=out)

c, n = collections.Counter(), 0
for i in range(0, len(keys), 100):
    res = call("POST", f"{BASE}/bulk/get", {"keys": keys[i:i + 100]})
    for v in (res.get("result") or {}).get("values", {}).values():
        n += 1
        try:
            g = json.loads(v) if isinstance(v, str) else v
        except Exception:
            c["(unparseable)"] += 1
            continue
        r = g.get("resource") if isinstance(g, dict) else None
        c[json.dumps(r) if r is not None else "(none)"] += 1
print(f"values read: {n}", file=out)
for k, v in c.most_common():
    print(f"{v:5d}  {k}", file=out)

